// Shared test fixture: the hand-authored demo house (data/fixtures, generated by the API).
import demoHouse from "@data/fixtures/demo-house.model.json";

import { parseBuildingModel } from "./model/parse";
import type { BuildingElement, BuildingModel } from "./model/types";

export function demoModelJson(): BuildingModel {
  return structuredClone(demoHouse) as BuildingModel;
}

export function demoIndex() {
  return parseBuildingModel(demoModelJson());
}

export function bySemanticKey(model: BuildingModel, key: string): BuildingElement {
  const el = model.elements.find((e) => e.semantic_key === key);
  if (!el) throw new Error(`no element ${key}`);
  return el;
}
